import React from 'react';

const Projects = ({ data }) => {
  const projects = data || [];

  return (
    <section style={{ padding:'100px 0' }}>
      <div style={{ maxWidth:1100, margin:'0 auto', padding:'0 2rem' }}>

        <div style={{ textAlign:'center', marginBottom:60 }}>
          <span style={{ fontFamily:"'DM Mono'", fontSize:'0.78rem', letterSpacing:'0.3em', textTransform:'uppercase', color:'#e8799a', display:'block', marginBottom:'0.75rem' }}>
            ✦ 03. work
          </span>
          <h2 style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:'clamp(2rem,5vw,3rem)', fontWeight:700, color:'#fdf0f4' }}>
            Featured <span style={{ color:'#e8799a', fontStyle:'italic' }}>Projects</span>
          </h2>
          <div style={{ width:60, height:3, background:'linear-gradient(90deg,#e8799a,#b882d4)', margin:'1.5rem auto 0', borderRadius:2 }} />
        </div>

        {projects.length === 0 ? (
          <div style={{ textAlign:'center', padding:'4rem 2rem', background:'rgba(34,18,40,0.72)', border:'1px solid rgba(232,121,154,0.14)', borderRadius:20 }}>
            <div style={{ fontSize:'3rem', marginBottom:'1rem' }}>🌸</div>
            <p style={{ color:'rgba(253,240,244,0.5)', fontFamily:"'Nunito'" }}>More projects coming soon!</p>
          </div>
        ) : (
          <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fit,minmax(340px,1fr))', gap:'2rem' }}>
            {projects.map((project, i) => (
              <div key={i} style={{
                background:'rgba(34,18,40,0.78)',
                border:'1px solid rgba(232,121,154,0.14)',
                borderRadius:22, backdropFilter:'blur(14px)',
                overflow:'hidden', transition:'all 0.4s cubic-bezier(0.16,1,0.3,1)',
                display:'flex', flexDirection:'column',
              }}
              onMouseEnter={e => { e.currentTarget.style.borderColor='rgba(232,121,154,0.4)'; e.currentTarget.style.boxShadow='0 20px 55px rgba(0,0,0,0.4), 0 0 30px rgba(232,121,154,0.12)'; e.currentTarget.style.transform='translateY(-6px)'; }}
              onMouseLeave={e => { e.currentTarget.style.borderColor='rgba(232,121,154,0.14)'; e.currentTarget.style.boxShadow='none'; e.currentTarget.style.transform='translateY(0)'; }}
              >
                {/* Banner */}
                <div style={{ height:180, background:'linear-gradient(135deg, rgba(232,121,154,0.15), rgba(184,130,212,0.15))', display:'flex', alignItems:'center', justifyContent:'center', position:'relative', overflow:'hidden' }}>
                  <div style={{ position:'absolute', inset:0, background:'linear-gradient(135deg, rgba(232,121,154,0.08), rgba(184,130,212,0.08))' }} />
                  {/* Decorative circles */}
                  <div style={{ position:'absolute', top:-30, right:-30, width:120, height:120, borderRadius:'50%', border:'1px solid rgba(232,121,154,0.15)' }} />
                  <div style={{ position:'absolute', bottom:-20, left:-20, width:90, height:90, borderRadius:'50%', border:'1px solid rgba(184,130,212,0.15)' }} />
                  <span style={{ fontSize:'3.5rem', position:'relative', zIndex:1 }}>🌸</span>
                  <div style={{ position:'absolute', top:'0.75rem', right:'0.75rem', padding:'0.25rem 0.75rem', background:'rgba(232,121,154,0.15)', border:'1px solid rgba(232,121,154,0.25)', borderRadius:'50px', fontFamily:"'DM Mono'", fontSize:'0.7rem', color:'#e8799a' }}>{project.category || 'frontend'}</div>
                </div>

                {/* Content */}
                <div style={{ padding:'1.75rem', flex:1, display:'flex', flexDirection:'column' }}>
                  <h3 style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:'1.4rem', fontWeight:700, color:'#fdf0f4', marginBottom:'0.75rem' }}>{project.title}</h3>
                  <p style={{ fontFamily:"'Nunito'", fontSize:'0.88rem', color:'rgba(253,240,244,0.6)', lineHeight:1.75, marginBottom:'1.25rem', flex:1 }}>{project.description}</p>

                  {/* Features */}
                  {project.features && (
                    <div style={{ marginBottom:'1.25rem' }}>
                      <div style={{ display:'flex', flexWrap:'wrap', gap:'0.4rem' }}>
                        {project.features.map((f,fi) => (
                          <span key={fi} style={{ padding:'0.2rem 0.65rem', background:'rgba(184,130,212,0.1)', border:'1px solid rgba(184,130,212,0.22)', borderRadius:'50px', fontFamily:"'Nunito'", fontSize:'0.75rem', color:'#d4a8e8' }}>{f}</span>
                        ))}
                      </div>
                    </div>
                  )}

                  {/* Tech stack */}
                  <div style={{ display:'flex', flexWrap:'wrap', gap:'0.4rem', marginBottom:'1.5rem' }}>
                    {project.technologies?.map((tech, ti) => (
                      <span key={ti} style={{ padding:'0.2rem 0.7rem', background:'rgba(232,121,154,0.08)', border:'1px solid rgba(232,121,154,0.22)', borderRadius:'50px', fontFamily:"'DM Mono'", fontSize:'0.72rem', color:'#f2a4bb' }}>{tech}</span>
                    ))}
                  </div>

                  {/* Links */}
                  <div style={{ display:'flex', gap:'0.75rem' }}>
                    {project.github && (
                      <a href={project.github} target="_blank" rel="noopener noreferrer"
                        style={{ padding:'0.5rem 1.1rem', border:'1px solid rgba(232,121,154,0.3)', borderRadius:'50px', fontFamily:"'Nunito'", fontSize:'0.82rem', color:'#e8799a', textDecoration:'none', display:'flex', alignItems:'center', gap:'0.4rem', transition:'all 0.2s ease' }}
                        onMouseEnter={e => { e.currentTarget.style.background='rgba(232,121,154,0.1)'; }}
                        onMouseLeave={e => { e.currentTarget.style.background='transparent'; }}
                      >GitHub</a>
                    )}
                    {project.live && (
                      <a href={project.live} target="_blank" rel="noopener noreferrer"
                        style={{ padding:'0.5rem 1.1rem', background:'linear-gradient(135deg,#e8799a,#b882d4)', borderRadius:'50px', fontFamily:"'Nunito'", fontSize:'0.82rem', color:'#fff', textDecoration:'none', display:'flex', alignItems:'center', gap:'0.4rem', fontWeight:600 }}
                      >Live Demo →</a>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </section>
  );
};

export default Projects;
